changeSet.sql:
INSERT INTO stretchy_report ( report_name, report_type, report_subtype, report_category, report_sql, description, core_report, use_report, self_service_user_report ) VALUES ( 'Balance de Saldos', 'Table', 'VisualBalanceSaldos', 'Accounting', $report$ WITH RECURSIVE selected_offices AS ( SELECT office_under.id, office_under.external_id FROM m_office selected_office JOIN m_office office_under ON office_under.hierarchy LIKE selected_office.hierarchy || '%' WHERE selected_office.id = CAST('${officeId}' AS BIGINT) AND office_under.hierarchy LIKE '${currentUserHierarchy}' || '%' ), legacy_account_names(account_code, account_name, parent_code) AS ( VALUES ('222099940101', 'RENDIMIENTO ACCIONES PREFERIDAS', '2220999401'), ('222099940102', 'DESEMBOLSO DE CREDITOS EN EFECTIVO SANTIAGO DE MARIA', '2220999401'), ('222099940103', 'DESEMBOLSOS DE CREDITOS EN EFECTIVO AGENCIA USULUTAN', '2220999401') ), account_nodes AS ( SELECT account.gl_code AS account_code, COALESCE(presentation.source_name, account.name) AS account_name, parent.gl_code AS parent_code FROM acc_gl_account account LEFT JOIN acc_gl_account parent ON parent.id = account.parent_id LEFT JOIN credesal_gl_account_presentation presentation ON presentation.gl_account_id = account.id
UNION ALL
SELECT legacy.account_code, legacy.account_name, legacy.parent_code FROM legacy_account_names legacy WHERE NOT EXISTS ( SELECT 1 FROM acc_gl_account account WHERE account.gl_code = legacy.account_code ) ), account_levels AS ( SELECT node.account_code, 0 AS account_level, ARRAY[node.account_code]::VARCHAR[] AS account_path FROM account_nodes node WHERE node.parent_code IS NULL
UNION ALL
SELECT child.account_code, parent.account_level + 1, parent.account_path || child.account_code FROM account_levels parent JOIN account_nodes child ON child.parent_code = parent.account_code WHERE NOT child.account_code = ANY(parent.account_path) ), direct_balances AS ( SELECT COALESCE(NULLIF(source_line.source_account_code, ''), native_account.gl_code) AS account_code, SUM( CASE WHEN COALESCE( presentation.balance_nature, CASE WHEN COALESCE(source_account.classification_enum, native_account.classification_enum) IN (1, 5) THEN 'D' ELSE 'A' END ) = 'D' THEN CASE WHEN journal_entry.type_enum = 2 THEN journal_entry.amount ELSE -journal_entry.amount END ELSE CASE WHEN journal_entry.type_enum = 1 THEN journal_entry.amount ELSE -journal_entry.amount END END ) AS balance, SUM(journal_entry.amount) FILTER ( WHERE journal_entry.entry_date = CAST('${endDate}' AS DATE) AND journal_entry.type_enum = 2 ) AS cutoff_debit, SUM(journal_entry.amount) FILTER ( WHERE journal_entry.entry_date = CAST('${endDate}' AS DATE) AND journal_entry.type_enum = 1 ) AS cutoff_credit FROM acc_gl_journal_entry journal_entry JOIN acc_gl_account native_account ON native_account.id = journal_entry.account_id LEFT JOIN credesal_arissto_gl_journal_line source_line ON source_line.target_journal_entry_id = journal_entry.id LEFT JOIN acc_gl_account source_account ON source_account.gl_code = source_line.source_account_code LEFT JOIN credesal_gl_account_presentation presentation ON presentation.gl_account_id = COALESCE(source_account.id, native_account.id) WHERE journal_entry.entry_date <= CAST('${endDate}' AS DATE) AND journal_entry.currency_code = 'USD' AND journal_entry.office_id IN (SELECT id FROM selected_offices) AND ( jsonb_typeof(journal_entry.dimensions -> 'office') IS DISTINCT FROM 'string' OR EXISTS ( SELECT 1 FROM selected_offices office WHERE office.id = journal_entry.office_id AND office.external_id = journal_entry.dimensions ->> 'office' ) ) GROUP BY COALESCE(NULLIF(source_line.source_account_code, ''), native_account.gl_code) ), visible_direct_balances AS ( SELECT direct.account_code, direct.balance FROM direct_balances direct WHERE direct.balance <> 0.00 OR COALESCE(direct.cutoff_debit, 0.00) <> 0.00 OR COALESCE(direct.cutoff_credit, 0.00) <> 0.00 ), account_rollup AS ( SELECT direct.account_code AS source_account_code, direct.account_code AS report_account_code, direct.balance, ARRAY[direct.account_code]::VARCHAR[] AS account_path FROM visible_direct_balances direct
UNION ALL
SELECT rollup.source_account_code, parent.account_code, rollup.balance, rollup.account_path || parent.account_code FROM account_rollup rollup JOIN account_nodes child ON child.account_code = rollup.report_account_code JOIN account_nodes parent ON parent.account_code = child.parent_code WHERE NOT parent.account_code = ANY(rollup.account_path) ), rolled_balances AS ( SELECT report_account_code AS account_code, ROUND(SUM(balance), 2) AS ending_balance FROM account_rollup GROUP BY report_account_code ) SELECT ROW_NUMBER() OVER (ORDER BY account.account_code COLLATE "C") AS display_order, CAST('${endDate}' AS DATE) AS as_of_date, account.account_code, account.parent_code, level.account_level, account.account_name AS account_description, rolled.ending_balance FROM rolled_balances rolled JOIN account_nodes account ON account.account_code = rolled.account_code JOIN account_levels level ON level.account_code = account.account_code ORDER BY display_order $report$, 'Saldo final por cuenta y sus rollups al corte, filtrado por oficina.', FALSE, TRUE, FALSE ) ON CONFLICT (report_name) DO UPDATE SET report_type = EXCLUDED.report_type, report_subtype = EXCLUDED.report_subtype, report_category = EXCLUDED.report_category, report_sql = EXCLUDED.report_sql, description = EXCLUDED.description, core_report = EXCLUDED.core_report, use_report = EXCLUDED.use_report, self_service_user_report = EXCLUDED.self_service_user_report;
DELETE FROM stretchy_report_parameter WHERE report_id = ( SELECT id FROM stretchy_report WHERE report_name = 'Balance de Saldos' );
INSERT INTO stretchy_report_parameter ( report_id, parameter_id, report_parameter_name ) SELECT report.id, parameter.id, parameter.parameter_variable FROM stretchy_report report JOIN stretchy_parameter parameter ON parameter.parameter_name IN ('OfficeIdSelectOne', 'endDateSelect') WHERE report.report_name = 'Balance de Saldos';
DO $validation$ BEGIN IF ( SELECT COUNT(*) FROM stretchy_report_parameter usage JOIN stretchy_report report ON report.id = usage.report_id WHERE report.report_name = 'Balance de Saldos' AND usage.report_parameter_name IN ('officeId', 'endDate') ) <> 2 THEN RAISE EXCEPTION 'Balance de Saldos requires officeId and endDate parameters'; END IF; END $validation$;
INSERT INTO m_permission ( grouping, code, entity_name, action_name, can_maker_checker ) SELECT 'report', 'READ_Balance de Saldos', 'Balance de Saldos', 'READ', FALSE WHERE NOT EXISTS ( SELECT 1 FROM m_permission WHERE code = 'READ_Balance de Saldos' );
